int main(void) {
    uint8_t buf[256];
    for (int i = 0; i < 256; i++) buf[i] = (uint8_t)i;
    op_crypt_block(2, 1, buf, sizeof buf, 0x12345678u);
    CHECK(memcmp(buf, cyc1, 256) == 0);
    op_crypt_block(2, 0, buf, sizeof buf, 0x12345678u);
    for (int i = 0; i < 256; i++) CHECK(buf[i] == i);
    op_crypt_block(2, 1, buf, sizeof buf, 0xDEADBEEFu);                  /* another key: another stream, same round trip */
    CHECK(memcmp(buf, cyc1, 256) != 0);
    op_crypt_block(2, 0, buf, sizeof buf, 0xDEADBEEFu);
    for (int i = 0; i < 256; i++) CHECK(buf[i] == i);
    op_crypt_block(1, 1, buf, sizeof buf, 0);
    op_crypt_block(1, 0, buf, sizeof buf, 0);
    for (int i = 0; i < 256; i++) CHECK(buf[i] == i);
    buf[0] = 0; op_crypt_block(1, 0, buf, 1, 0);
    CHECK(buf[0] == 0x47);                                               /* first entry of mpbbI */
    op_crypt_block(0, 1, buf, 1, 0);                                     /* method 0 leaves data alone */
    CHECK(buf[0] == 0x47);

    uint8_t want[1536 + 64], got[1536 + 64];
    size_t wn = 0;
    for (int r = 0; r < 6; r++) for (int i = 0; i < 256; i++) want[wn++] = (uint8_t)i;
    const char *tail = "hello hello hello hello world, world, world";
    memcpy(want + wn, tail, strlen(tail)); wn += strlen(tail);
    CHECK(op_zinflate(z_stored, sizeof z_stored, got, wn) == 0 && memcmp(got, want, wn) == 0);
    CHECK(op_zinflate(z_l1, sizeof z_l1, got, wn) == 0 && memcmp(got, want, wn) == 0);
    CHECK(op_zinflate(z_l9, sizeof z_l9, got, wn) == 0 && memcmp(got, want, wn) == 0);
    CHECK(op_zinflate(z_fixed, sizeof z_fixed, got, 12) == 0 && memcmp(got, "abcabcabcabc", 12) == 0);
    CHECK(op_zinflate(z_l9, sizeof z_l9, got, wn - 1) != 0);              /* output limit */
    CHECK(op_zinflate(z_l9, sizeof z_l9 - 8, got, wn) != 0);              /* truncated input */
    CHECK(op_zinflate(z_l1, 1, got, wn) != 0);
    uint8_t bad[sizeof z_l1];
    for (int round = 0; round < 64; round++) {                           /* corrupt input must fail or finish, never crash (run under ASAN) */
        memcpy(bad, z_l1, sizeof bad);
        for (size_t i = 2 + (size_t)round % 5; i < sizeof bad; i += 3 + (size_t)round % 7) bad[i] ^= (uint8_t)(0x11 * (round + 1));
        (void)op_zinflate(bad, sizeof bad, got, wn);
    }
    printf("%d checks, %d failed", checks, fails);
    putchar(10);
    return fails != 0;
}
